				 *
				 * @default 1 day (60 * 60 * 24)
				 */
				freshAge?: number;
		  })
		| undefined;
	account?:
		| (BetterAuthDBOptions<"account", keyof BaseAccount> & {
				/**
				 * When enabled (true), the user account data (accessToken, idToken, refreshToken, etc.)
