     */
    data: {
      user: User;
      url: string;
      token: string;
    },
    /**
     * The request object
     */
    request?: Request) => Promise<void>;
    /**
     * Number of seconds the reset password token is
     * valid for.
     * @default 1 hour (60 * 60)
     */
    resetPasswordTokenExpiresIn?: number;
    /**
     * A callback function that is triggered
