import { drizzleAdapter } from "@better-auth/drizzle-adapter";
import { oauthProvider } from "@better-auth/oauth-provider";
import { betterAuth } from "better-auth/minimal";
import { jwt } from "better-auth/plugins/jwt";
import { createDb } from "../db";
import * as authSchema from "../db/auth-schema";

export type DevelopmentEmailKind = "invitation" | "password-reset" | "verification";

export interface DevelopmentEmailMessage {
  kind: DevelopmentEmailKind;
  email: string;
  token: string;
  url: string;
}

const developmentEmailSink: DevelopmentEmailMessage[] = [];

export interface AuthEnvironment {
  DB: D1Database;
  BETTER_AUTH_SECRET: string;
  BETTER_AUTH_URL: string;
  BOOTSTRAP_TOKEN?: string;
  DEV_EMAIL_SINK?: string;
}

export function readDevelopmentEmailSink(): readonly DevelopmentEmailMessage[] {
  return developmentEmailSink.slice();
}

export function clearDevelopmentEmailSink() {
  developmentEmailSink.length = 0;
}

export function recordDevelopmentEmail(
  environment: Pick<AuthEnvironment, "BETTER_AUTH_URL" | "DEV_EMAIL_SINK">,
  message: DevelopmentEmailMessage,
) {
  const isLocalDevelopment =
    environment.DEV_EMAIL_SINK === "true" ||
    environment.BETTER_AUTH_URL.startsWith("http://localhost") ||
    environment.BETTER_AUTH_URL.startsWith("http://127.0.0.1");

  if (!isLocalDevelopment) return;

  developmentEmailSink.push(message);
  if (developmentEmailSink.length > 100) developmentEmailSink.shift();
}

export function createAuth(environment: AuthEnvironment) {
  const resourceIdentifier = `${environment.BETTER_AUTH_URL}/api`;

  return betterAuth({
    appName: "Shui",
    basePath: "/api/auth",
    baseURL: environment.BETTER_AUTH_URL,
    database: drizzleAdapter(createDb(environment.DB), {
      provider: "sqlite",
      schema: authSchema,
      transaction: false,
    }),
    disabledPaths: ["/token"],
    emailAndPassword: {
      enabled: true,
      autoSignIn: false,
      disableSignUp: true,
      requireEmailVerification: true,
      revokeSessionsOnPasswordReset: true,
      sendResetPassword: async ({ user, url, token }) => {
        recordDevelopmentEmail(environment, {
          email: user.email,
          kind: "password-reset",
          token,
          url,
        });
      },
    },
    emailVerification: {
      autoSignInAfterVerification: false,
      sendOnSignIn: true,
      sendOnSignUp: true,
      sendVerificationEmail: async ({ user, url, token }) => {
        recordDevelopmentEmail(environment, {
          email: user.email,
          kind: "verification",
          token,
          url,
        });
      },
    },
    plugins: [
      jwt(),
      oauthProvider({
        allowDynamicClientRegistration: false,
        allowUnauthenticatedClientRegistration: false,
        clientRegistrationAllowedResources: [resourceIdentifier],
        clientRegistrationDefaultResources: [resourceIdentifier],
        consentPage: "/consent",
        enforcePerClientResources: true,
        grantTypes: ["authorization_code", "client_credentials"],
        loginPage: "/sign-in",
        resources: [
          {
            accessTokenTtl: 3600,
            allowedScopes: ["openid", "profile", "email", "api:read"],
            identifier: resourceIdentifier,
            name: "Shui API",
          },
        ],
        scopes: ["openid", "profile", "email", "api:read"],
      }),
    ],
    secret: environment.BETTER_AUTH_SECRET,
    rateLimit: {
      customRules: {
        "/request-password-reset": { max: 5, window: 60 },
        "/sign-in/email": { max: 5, window: 60 },
        "/sign-up/email": { max: 5, window: 60 },
      },
      customStorage: {
        consume: async (key, rule) => consumeRateLimit(environment.DB, key, rule),
      },
      enabled: true,
    },
    databaseHooks: {
      session: {
        create: {
          before: async (session) => {
            try {
              const principal = await environment.DB.prepare(
                `SELECT 1 AS ok
                   FROM human_principals AS hp
                   JOIN principals AS p ON p.id = hp.principal_id
                  WHERE hp.user_id = ?
                    AND hp.status = 'active'
                    AND hp.disabled = 0
                    AND p.type = 'human'
                    AND p.status = 'active'
                  LIMIT 1`,
              )
                .bind(session.userId)
                .first<{ ok: number }>();

              return principal?.ok === 1;
            } catch {
              return false;
            }
          },
        },
      },
    },
    telemetry: {
      enabled: false,
    },
    trustedOrigins: [environment.BETTER_AUTH_URL],
  });
}

export type AuthInstance = ReturnType<typeof createAuth>;

async function consumeRateLimit(
  database: D1Database,
  key: string,
  rule: { max: number; window: number },
) {
  const now = Date.now();
  const windowMilliseconds = rule.window * 1000;
  const bucket = await database
    .prepare(
      `INSERT INTO rate_limit_buckets
        (bucket_key, window_started_at, count, updated_at)
       VALUES (?, ?, 1, ?)
       ON CONFLICT(bucket_key) DO UPDATE SET
         count = CASE
           WHEN rate_limit_buckets.window_started_at + ? <= ? THEN 1
           ELSE rate_limit_buckets.count + 1
         END,
         window_started_at = CASE
           WHEN rate_limit_buckets.window_started_at + ? <= ? THEN ?
           ELSE rate_limit_buckets.window_started_at
         END,
         updated_at = ?
       RETURNING count, window_started_at`,
    )
    .bind(key, now, now, windowMilliseconds, now, windowMilliseconds, now, now, now)
    .first<{ count: number; window_started_at: number }>();

  if (!bucket) return { allowed: false, retryAfter: rule.window };

  const retryAfter = Math.max(
    0,
    Math.ceil((bucket.window_started_at + windowMilliseconds - now) / 1000),
  );

  return {
    allowed: bucket.count <= rule.max,
    retryAfter,
  };
}

